import os, re, nbformat
R=""; ok=lambda c,m: print(("PASS " if c else "FAIL ")+m)
for f in ["README.md","generate_data.py","student_eda.ipynb","board_report.ipynb","figures/before.png","figures/after.png","reports/duka_board_report.png","dashboard.md","requirements.txt"]: ok(os.path.exists(R+f),"exists "+f)
rd=open(R+"README.md", encoding="utf-8").read(); bs=re.search(r"## Board Summary \(150 words\)\n(.*?)\n\n##",rd,re.S).group(1); ok(len(bs.split())==150,f"Board Summary words = {len(bs.split())}")
ok("![" in rd and "reports/duka_board_report.png" in rd,"README embeds report image"); ok(len(re.findall(r"^\d\. \*\*",rd,re.M))>=5,"README five insights"); ok("student_eda.ipynb" in rd and "python generate_data.py" in rd,"README how to run")
g=open(R+"generate_data.py", encoding="utf-8").read(); ok("default_rng(55)" in g and "default_rng(2026)" in g,"both seeds in generate_data")
s=nbformat.read(R+"student_eda.ipynb",4); md=" ".join(c.source for c in s.cells if c.cell_type=="markdown"); cd=" ".join(c.source for c in s.cells if c.cell_type=="code")
heads=[l for c in s.cells if c.cell_type=="markdown" for l in c.source.split("\n") if l.startswith("## ")]; print("  headings:",heads)
for h in ["Structure","Univariate","Bivariate","Multivariate","Hypotheses","Findings","Recommendations","Limitations"]: ok(any(h in x for x in heads),"student_eda section "+h)
ok("average_score" in cd and "performance_band" in cd and "pd.cut" in cd,"avg score + band"); ok(".corr(" in cd,"correlation matrix"); ok("pivot_table" in cd,"pivot tables"); ok("polyfit" in cd and "R²" in md and "Limitation" in md,"trend line slope/R2/limitation")
ok(all(n in md or n in cd for n in ["01_hist_average_score","03_bar_at_risk_by_county","04_box_score_by_school_type"]),"figures referenced by name"); ok("savefig" in cd,"savefig used")
ok(sum(o.output_type=="error" for c in s.cells if c.cell_type=="code" for o in c.outputs)==0,"student_eda no errors")
b=nbformat.read(R+"board_report.ipynb",4); firstcode=next(i for i,c in enumerate(b.cells) if c.cell_type=="code"); pre=" ".join(c.source for c in b.cells[:firstcode])
ok(all(k in pre for k in ["Audience","Decision","Big Idea","SCR"]),"storyboard before first code cell")
bm=" ".join(c.source for c in b.cells if c.cell_type=="markdown"); ok("Design change" in bm and "before.png" in " ".join(c.source for c in b.cells),"before/after + explanation")
ok(sum(o.output_type=="error" for c in b.cells if c.cell_type=="code" for o in c.outputs)==0,"board_report no errors")
rq=open(R+"requirements.txt", encoding="utf-8").read().split(); ok({"pandas","numpy","matplotlib","seaborn"}<=set(rq),"requirements")
dm=open(R+"dashboard.md", encoding="utf-8").read(); ok("Looker" in dm and dm.count("![")>=2,"dashboard.md Looker + >=2 screenshots (link still placeholder)")
# --- extra checks: stale files and unfinished dashboard.md
for f in ["student_performance_eda.ipynb","build_report.py","board_report.png","board_report.pdf","duka_board_report.png","dashboard.html","reports/board_report.png","reports/board_report.pdf","figures/05_bar_score_by_study_quartile.png"]:
    ok(not os.path.exists(R+f), "stale file removed: "+f)
dm=open(R+"dashboard.md", encoding="utf-8").read()
ok("PASTE YOUR LINK HERE" not in dm and "⚠️" not in dm, "dashboard.md placeholders replaced")
ok(bool(re.search(r"https://lookerstudio\.google\.com/\S+", dm)), "dashboard.md has a Looker Studio link")
ok(os.path.exists(R+"screenshots/looker_1_overview.png") and os.path.exists(R+"screenshots/looker_2_filtered.png"), "two Looker screenshots exist")
